package io.openaev.rest.catalog_connector;import io.openaev.aop.RBAC;import io.openaev.database.model.Action;import io.openaev.database.model.CatalogConnector;import io.openaev.database.model.ResourceType;import io.openaev.rest.helper.RestBehavior;import io.openaev.service.CatalogConnectorService;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.RestController;import java.util.List;@RestController@RequiredArgsConstructorpublic class CatalogConnectorApi extends RestBehavior {    public static final String CATALOG_CONNECTOR_URI = "/api/connectors";    private final CatalogConnectorService catalogConnectorService;    @GetMapping(CATALOG_CONNECTOR_URI)    @RBAC(actionPerformed = Action.READ, resourceType = ResourceType.CATALOG)    public List<CatalogConnector> getCatalogConnector() {return this.catalogConnectorService.catalogConnectors();}}